function validate([name, typed]) {
  if (typeof name !== 'string' || name.length < 1 || name.length > 1000) return 'name needs 1 to 1000 characters.';
  if (typeof typed !== 'string' || typed.length < 1 || typed.length > 1000) return 'typed needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(name) || !/^[a-z]+$/.test(typed)) return 'Use only lowercase English letters.';
  return null;
}

