function isLongPressedName(name, typed) {
  const runs = (s) => {
    const out = [];
    for (const ch of s) {
      if (out.length && out[out.length - 1][0] === ch) out[out.length - 1][1]++;
      else out.push([ch, 1]);
    }
    return out;
  };
  const a = runs(name), b = runs(typed);
  if (a.length !== b.length) return false;
  return a.every(([ch, count], k) => b[k][0] === ch && b[k][1] >= count);
}

