function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alpha = large ? (rand() < 0.5 ? 3 : 26) : 1 + Math.floor(rand() * 3);
  const pick = () => letters[Math.floor(rand() * alpha)];
  const limit = large ? 1000 : 12;
  const n = large ? 300 + Math.floor(rand() * 300) : 1 + Math.floor(rand() * 6);
  let name = '';
  for (let k = 0; k < n; k++) name += pick();
  // Stretch some characters while leaving room for the rest of the name.
  let typed = '';
  for (let k = 0; k < n; k++) {
    const room = limit - typed.length - (n - k);
    const extra = rand() < 0.35 ? Math.min(room, Math.floor(rand() * 4)) : 0;
    typed += name[k].repeat(1 + extra);
  }
  const mode = rand();
  if (mode < 0.5) return [name, typed];
  const chars = typed.split('');
  const at = Math.floor(rand() * chars.length);
  if (mode < 0.65) chars[at] = pick();
  else if (mode < 0.8 && chars.length > 1) chars.splice(at, 1);
  else if (mode < 0.92 && chars.length < limit) chars.splice(at + (rand() < 0.5 ? 0 : 1), 0, pick());
  else if (!large) return [name, Array.from({ length: 1 + Math.floor(rand() * 8) }, pick).join('')];
  else chars.reverse();
  return [name, chars.join('')];
}
